* {
    padding: 0;
    margin: 0;
    -webkit-box-sizing: border-box;
    -moz-box-sizing: border-box;
    -o-box-sizing: border-box
}

.disabled {
    display: none!important
}

.owl-item {
    display: inline-block;
    vertical-align: text-top
}

button,form,input,select,textarea {
    border: 0;
    background: 0;
    outline: 0
}

.text-center {
    text-align: center
}

.text-left {
    text-align: left
}

.text-right {
    text-align: right
}

.before:before {
    content: '';
    position: absolute;
    width: 100%;
    height: 100%;
    top: 0;
    right: 0;
    z-index: 5
}

.after:after {
    content: '';
    position: absolute;
    width: 100%;
    height: 100%;
    top: 0;
    right: 0;
    z-index: 5
}

flex-center,.flex-center {
    display: flex;
    flex-wrap: wrap;
    justify-content: center
}

flex-start,.flex-start {
    display: flex;
    flex-wrap: wrap;
    justify-content: flex-start
}

.align-center {
    align-items: center
}

.flex-end {
    display: flex;
    flex-wrap: wrap;
    justify-content: flex-end;
    align-items: center;
    flex-direction: row-reverse;
}

.flex-1 {
